INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0db3eada27aef13b8b710c90e52c698', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vector_algebra', 'Vector Algebra', 'Coplanar vectors condition', '["math_12_jm_3d_geometry"]', '["scalar triple product","coplanar vectors","vector cross product","determinant","linear equation","vector dot product"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'If the vectors $\vec{a} = 2\hat{i} + 3\hat{j} - \hat{k}$, $\vec{b} = \hat{i} - 2\hat{j} + 4\hat{k}$, and $\vec{c} = x\hat{i} + \hat{j} + z\hat{k}$ are coplanar, then the values of $x$ and $z$ must satisfy which of the following equations?

$$
\text{A. } 11x + 9z = 7 \quad
\text{B. } 11x - 9z = -7 \quad
\text{C. } 9x + 11z = 7 \quad
\text{D. } 9x - 11z = -7
$$', '["11x + 9z = 7", "11x - 9z = -7", "9x + 11z = 7", "9x - 11z = -7"]', '11x - 9z = -7', 'Three vectors are coplanar if their scalar triple product is zero. Compute $[\vec{a}\ \vec{b}\ \vec{c}] = \vec{a} \cdot (\vec{b} \times \vec{c}) = 0$. First, compute $\vec{b} \times \vec{c}$, then take dot product with $\vec{a}$. After simplification, the condition becomes $11x - 9z = -7$, which is the required relation.', '["Step 1: Use scalar triple product condition: $\\vec{a} \\cdot (\\vec{b} \\times \\vec{c}) = 0$", "Step 2: Compute $\\vec{b} \\times \\vec{c}$ using determinant method", "Step 3: Take dot product with $\\vec{a} = (2,3,-1)$", "Step 4: Simplify the expression to get linear equation in $x$ and $z$", "Step 5: Match with given options"]', '$\vec{a} \cdot (\vec{b} \times \vec{c}) = 0$', 'math.vector_algebra.scalar_triple_product_sign_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:08:40.677Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0dc5d7e447fdfc10f3a261bb3a2231d', 'NEET', '11', 'Biology', 'bio_11_nervous_cns_brain', 'Nervous System', 'Brain functions', '[]', '["cerebellum","motor coordination","voluntary movement","brain anatomy"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 3, -1.0, 'Which part of the brain is primarily responsible for the coordination of voluntary skeletal muscle movements?', '["Cerebellum", "Medulla oblongata", "Pons", "Hypothalamus"]', 'Cerebellum', 'The cerebellum integrates sensory input and fine‑tunes motor activity, making it essential for the smooth execution of voluntary movements.', '["Step 1: Identify the brain region involved in motor coordination.", "Step 2: Recall that the cerebellum processes proprioceptive information to regulate movement.", "Step 3: Choose the option that matches this function."]', '', 'biology.neuro.brain.cerebellum_function', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:59:25.052Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0dcfed1747ba3eebdfcb78921bb11af', 'NEET', '11', 'Biology', 'bio_11_neet_peristalsis_segmentation', 'Digestion and Absorption', 'Peristalsis and segmentation movements', '[]', '["intestinal motility","peristalsis","segmentation","mixing vs propulsion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'Which statement correctly distinguishes peristalsis from segmentation movements in the small intestine?', '["Peristalsis mixes intestinal contents while segmentation propels them forward.", "Peristalsis propels contents unidirectionally; segmentation primarily mixes contents without net movement.", "Both peristalsis and segmentation produce net forward movement, but peristalsis is slower.", "Segmentation occurs only in the large intestine, whereas peristalsis is exclusive to the small intestine."]', 'Peristalsis propels contents unidirectionally; segmentation primarily mixes contents without net movement.', 'Peristalsis involves coordinated circular and longitudinal muscle contractions that push chyme forward. Segmentation consists of alternating contractions that churn the contents, enhancing mixing but causing little overall displacement.', '["Step 1: Recall the definition of peristalsis – a wave‑like contraction that moves contents forward.", "Step 2: Recall the definition of segmentation – localized contractions that mix contents.", "Step 3: Compare the functional outcomes of each movement.", "Step 4: Choose the option that matches the correct functional description."]', '', 'biology.digestive.peristalsis_vs_segmentation', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:53.678Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0dd4044b3484726cb2e2572e6e63779', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_electrocyclic', 'Chemistry', 'Advanced Organic Mechanisms', '["chem_12_ja_organic_mechanisms"]', '["electrocyclic reaction","Woodward-Hoffmann rules","thermal reaction","conrotatory","disrotatory","hexatriene","symmetry allowed"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'Consider the thermal ring‑closure of trans‑1,3,5‑hexatriene to cyclohexadiene. Which of the following statements are correct? (Select all that apply.)', '["The reaction proceeds via a conrotatory mechanism.", "The reaction proceeds via a disrotatory mechanism.", "The product formed is the cis‑cyclohexadiene.", "The reaction is symmetry‑allowed under thermal conditions."]', '["THE REACTION PROCEEDS VIA A CONROTATORY MECHANISM.", "THE REACTION IS SYMMETRY‑ALLOWED UNDER THERMAL CONDITIONS."]', 'A 6‑π electron electrocyclic reaction under thermal conditions follows the Woodward‑Hoffmann rule: it must be conrotatory and is symmetry‑allowed. Disrotatory closure is forbidden, and the product is the trans‑cyclohexadiene, not the cis isomer.', '["Step 1: Count the number of π electrons (6) in the reacting system.", "Step 2: Apply the Woodward‑Hoffmann rule for a thermal electrocyclic reaction (4n+2 electrons → conrotatory).", "Step 3: Determine the stereochemistry of the product (trans‑cyclohexadiene).", "Step 4: Identify which statements reflect the conrotatory, symmetry‑allowed nature of the reaction.", "Step 5: Mark the correct statements."]', 'Woodward‑Hoffmann rule: for a thermal electrocyclic reaction, a system with 4n+2 π electrons undergoes conrotatory closure.', 'chem.organic.electrocyclic.woodward_hoffmann', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:46:33.732Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0e1787f8fba31a8c8bb6c90fcdb6bcd', 'NEET', '11', 'Biology', 'bio_11_biomolecules_proteins', 'Biomolecules', 'Protein structure', '[]', '["protein structure","hydrogen bonding","secondary structure","alpha helix","beta sheet"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly describes the level of protein structure that is primarily stabilized by hydrogen bonds between the carbonyl oxygen and amide hydrogen of the peptide backbone?', '["Primary structure", "Secondary structure", "Tertiary structure", "Quaternary structure"]', 'Secondary structure', 'Hydrogen bonds between the carbonyl oxygen and amide hydrogen of the peptide backbone form α‑helices and β‑sheets, which define the secondary structure of a protein.', '["Step 1: List the four levels of protein structure.", "Step 2: Identify which level is stabilized mainly by hydrogen bonds between backbone atoms.", "Step 3: Choose the level that matches this description."]', '', 'biology.proteins.secondary_structure_hbond', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:57:55.542Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0edaea2dee090d3788d389d0bfddc14', 'NEET', '12', 'Biology', 'bio_12_neet_genetics', 'Principles of Inheritance and Variation', 'Pedigree analysis autosomal X-linked', '[]', '["pedigree analysis","autosomal dominant","inheritance pattern","genetics","X-linked","Mendelian disorders"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'In a pedigree, if a trait appears in both males and females equally and is expressed in every generation, it is most likely:', '["X-linked recessive", "Autosomal recessive", "X-linked dominant", "Autosomal dominant"]', 'Autosomal dominant', 'Autosomal dominant traits appear in every generation and affect both sexes equally without skipping.', '["Check expression in both sexes", "Observe no skipping generations", "Conclude autosomal dominant inheritance"]', '', 'biology.genetics.pedigree_sex_linked_misreading', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:19.959Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0f1063d48d5b58b23eeb021ff063d16', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Organic Chemistry', 'Named reactions mechanism Beckmann Baeyer-Villiger', '["chem_12_ja_rearrangement_reactions"]', '["Beckmann rearrangement","oxime","nitrilium ion","acid-catalyzed","migration"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'In the Beckmann rearrangement, what is the key intermediate formed from oxime under acidic conditions?', '["Carbocation", "Nitrene", "Nitrilium ion", "Carbanion"]', 'Nitrilium ion', 'Oxime protonates, loses water to form nitrilium ion, then rearranges.', '["Step 1: Protonation of oxime", "Step 2: Loss of H₂O forms nitrilium ion", "Step 3: Alkyl shift"]', '', 'chem.organic.beckmann.intermediate_confusion', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:17:29.057Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0f25a3d9c36e21485bfdbbc7d4fad03', 'Board', '9', 'Mathematics', 'math_09_board_linear_eq', 'Algebraic Expressions', 'Linear equations in two variables', '[]', '["simultaneous equations","substitution method","linear system"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 3, 0.0, 'Solve the system of equations: $2x + 3y = 7$ and $4x - y = 5$. What is the value of $x$?', '["1", "11/7", "2", "3"]', '11/7', 'From the second equation, $y = 4x - 5$. Substituting into the first gives $2x + 3(4x - 5) = 7 \Rightarrow 14x = 22 \Rightarrow x = 11/7$.', '["Step 1: Express $y$ from the second equation: $y = 4x - 5$.", "Step 2: Substitute this expression for $y$ into the first equation.", "Step 3: Solve the resulting single-variable equation for $x$."]', 'Substitution method for solving linear systems', 'math.algebra.linear.two_variables.substitution', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:11:01.823Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0f821da56243c0000091d947af10b23', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_haloalkanes', 'Haloalkanes and Haloarenes', 'Grignard reagent preparation reactions', '[]', '["Grignard reagent","organomagnesium compound","anhydrous conditions","halide reactivity"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following reactions will NOT lead to the formation of a Grignard reagent under standard anhydrous conditions?', '["Mg + CH₃Br \\rightarrow CH₃MgBr", "Mg + C₆H₅Cl \\rightarrow C₆H₅MgCl", "Mg + CH₃I \\rightarrow CH₃MgI", "Mg + CH₃Cl \\rightarrow CH₃MgCl (in presence of moisture)"]', 'Mg + CH₃Cl \rightarrow CH₃MgCl (in presence of moisture)', 'Grignard reagents are prepared from alkyl or aryl halides (iodide, bromide, or chloride) in dry ether. Chlorides are much less reactive, and any moisture destroys the organomagnesium compound. Hence the reaction with CH₃Cl in the presence of moisture does not give a Grignard reagent.', '["Step 1: Identify that Grignard reagents require anhydrous conditions; moisture leads to hydrolysis.", "Step 2: Recognise that alkyl bromides and iodides react readily with Mg, while chlorides are sluggish.", "Step 3: Conclude that the only listed reaction that fails to produce a Grignard reagent is the one involving CH₃Cl with moisture present."]', '', 'chemistry.haloalkanes.grignard_moisture_trap', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:06:45.561Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0f891ed0018808a5caf38f211b68609', 'JEEMains', '12', 'Mathematics', 'math_12_jm_3d_geometry', 'Three Dimensional Geometry', 'Equation of plane — normal form intercept form', '[]', '["Equation of plane","Normal form","Intercept form","Three Dimensional Geometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 4, -1.0, '$$\vec{n} \perp \vec{r} \Rightarrow \vec{n} \cdot \vec{r} = d$$
$$\vec{n} = \langle a, b, c \rangle$$
$$\vec{r} = \langle x, y, z \rangle$$
$$d = \text{constant}$$

Find the equation of the plane in intercept form, given that the plane passes through the point $$(2, 3, 4).$$', '["$$\\frac{x}{a} + \\frac{y}{b} + \\frac{z}{c} = 1$$", "$$\\frac{x}{2} + \\frac{y}{3} + \\frac{z}{4} = 1$$", "$$\\frac{x}{a} + \\frac{y}{b} + \\frac{z}{c} = \\frac{d}{\\sqrt{a^2 + b^2 + c^2}}$$", "$$\\frac{x}{2} + \\frac{y}{3} + \\frac{z}{4} = \\frac{d}{\\sqrt{2^2 + 3^2 + 4^2}}$$"]', '$$\frac{x}{a} + \frac{y}{b} + \frac{z}{c} = \frac{d}{\sqrt{a^2 + b^2 + c^2}}$$', 'Step 1: Recall the normal form of the equation of a plane, which is given by $$\vec{n} \cdot \vec{r} = d.$$,Step 2: Substitute the given normal vector $$\vec{n} = \langle a, b, c \rangle$$ and the point $$(2, 3, 4)$$ into the equation to get $$\langle a, b, c \rangle \cdot \langle x, y, z \rangle = d.$$,Step 3: Simplify the equation to get $$ax + by + cz = d.$$,Step 4: Divide both sides of the equation by $$\sqrt{a^2 + b^2 + c^2}$$ to get the intercept form of the equation of the plane, which is $$\frac{x}{a} + \frac{y}{b} + \frac{z}{c} = \frac{d}{\sqrt{a^2 + b^2 + c^2}}.$$', '["Step 1: Recall the normal form of the equation of a plane, which is given by $$\\vec{n} \\cdot \\vec{r} = d.$$", "Step 2: Substitute the given normal vector $$\\vec{n} = \\langle a, b, c \\rangle$$ and the point $$(2, 3, 4)$$ into the equation to get $$\\langle a, b, c \\rangle \\cdot \\langle x, y, z \\rangle = d.$$", "Step 3: Simplify the equation to get $$ax + by + cz = d.$$", "Step 4: Divide both sides of the equation by $$\\sqrt{a^2 + b^2 + c^2}$$ to get the intercept form of the equation of the plane, which is $$\\frac{x}{a} + \\frac{y}{b} + \\frac{z}{c} = \\frac{d}{\\sqrt{a^2 + b^2 + c^2}}.$$"]', '\vec{n} \cdot \vec{r} = d', 'math.geometry.plane.normal_form_intercept_form', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:21:45.463Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a0f9d360617d50c3fe99c686b3a27776', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_friedel_crafts', 'Hydrocarbons', 'Friedel‑Crafts Reactions', '[]', '["Friedel‑Crafts acylation","acylium ion","aromatic ketone","AlCl₃ catalyst","electrophilic substitution"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements correctly describes Friedel‑Crafts acylation of an aromatic ring?', '["Alkylation uses an acid chloride as the electrophile.", "Acylation of an aromatic ring yields an aromatic ketone.", "Alkylation does not lead to carbocation rearrangement.", "Acylation requires AlCl₃ and an alkyl halide."]', 'Acylation of an aromatic ring yields an aromatic ketone.', 'In Friedel‑Crafts acylation the electrophile is an acylium ion generated from an acid chloride and AlCl₃. The reaction introduces an acyl group, producing an aromatic ketone as the product.', '["Step 1: Identify the electrophile used in Friedel‑Crafts acylation (acid chloride → acylium ion).", "Step 2: Recognize that the product is an aromatic ketone.", "Step 3: Choose the option that matches these facts."]', 'R–C=O⁺AlCl₄⁻ (acylation)', 'chemistry.organic.friedel_crafts_acylation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:51.407Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a10487820f18243fbb02f09e4258de84', 'JEEMains', '11', 'Physics', 'phy_11_jm_waves', 'Waves', 'Wave equation', '[]', '["wave speed","angular frequency","wave number","relation v=ω/k"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A progressive wave traveling along a string is described by $y = 0.04 \sin(5\pi x - 20\pi t)$, where $y$ is in meters, $x$ in meters and $t$ in seconds. What is the speed of the wave in m/s?', '["4 m/s", "5 m/s", "8 m/s", "10 m/s"]', '4 m/s', 'The wave speed $v$ is given by $v = \frac{\omega}{k}$. From the argument we read $\omega = 20\pi\,\text{rad/s}$ and $k = 5\pi\,\text{rad/m}$, so $v = (20\pi)/(5\pi) = 4\,\text{m/s}$.', '["Step 1: Identify $\\omega = 20\\pi$ rad/s and $k = 5\\pi$ rad/m from the wave argument.", "Step 2: Use the relation $v = \\frac{\\omega}{k}$.", "Step 3: Substitute the values and simplify to obtain $v = 4$ m/s."]', 'v = \frac{\omega}{k}', 'physics.waves.speed_relation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:49.959Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a106128d16e886402517a2f537cbf841', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_combinatorics', 'Advanced Combinatorics', 'Inclusion-exclusion principle — multi-set applications', '["math_12_ja_number_theory"]', '["multisets","subset sum","integer solutions","bounded variables","generating functions","case analysis","combinatorial counting"]', 1, 0, '[]', 'Integer', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 6, -1.0, 'A multiset contains 10 copies of the number 1, 8 copies of 2, and 6 copies of 3. How many distinct subsets of this multiset have a sum of exactly 10?', '[]', '28', 'We need to count non-negative integer solutions to $ x + 2y + 3z = 10 $ with $ x \leq 10, y \leq 8, z \leq 6 $. Fix $ z $ from 0 to 3 (since $ 3z \leq 10 $), then for each $ z $, solve $ x + 2y = 10 - 3z $. For each such equation, count valid $ y $ such that $ 2y \leq 10 - 3z $ and $ y \leq 8 $, then $ x = 10 - 3z - 2y \geq 0 $ and $ x \leq 10 $. Summing over $ z = 0 $ to $ 3 $, we get total 28 valid combinations.', '["Step 1: Model problem as $ x + 2y + 3z = 10 $, $ 0 \\leq x \\leq 10, 0 \\leq y \\leq 8, 0 \\leq z \\leq 6 $", "Step 2: Loop over possible $ z $: 0 to 3", "Step 3: For each $ z $, compute $ s = 10 - 3z $", "Step 4: Count integer $ y $ such that $ 0 \\leq 2y \\leq s $ and $ y \\leq 8 $", "Step 5: For each such $ y $, $ x = s - 2y \\geq 0 $, and $ x \\leq 10 $ is automatically satisfied", "Step 6: Total valid combinations: 28"]', 'x + 2y + 3z = 10 with bounds', 'math.combinatorics.multiset_sum_bounds', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:17:18.217Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a107eb423fd08418411e09fed2184f79', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals_substitution', 'Integrals', 'Integration by substitution', '["math_12_jm_functions_composition"]', '["integration by substitution","trigonometric integral","chain rule reverse","u-substitution","composite functions"]', 1, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, 0.0, 'Evaluate the integral $\int \frac{\sin(\sqrt{x})}{\sqrt{x}} \, dx$ using a suitable substitution.', '[]', '-2', 'Let $u = \sqrt{x}$, so $du = \frac{1}{2\sqrt{x}}dx$, which implies $2du = \frac{1}{\sqrt{x}}dx$. Substituting, the integral becomes $\int 2\sin(u)\,du = -2\cos(u) + C = -2\cos(\sqrt{x}) + C$. The answer is the antiderivative without constant.', '["Step 1: Choose substitution: $u = \\sqrt{x}$, so $du = \\frac{1}{2\\sqrt{x}}dx$.", "Step 2: Rewrite differential: $\\frac{1}{\\sqrt{x}}dx = 2du$.", "Step 3: Substitute into integral: $\\int \\sin(u) \\cdot 2du = 2\\int \\sin(u)du$.", "Step 4: Integrate: $2(-\\cos(u)) = -2\\cos(u)$.", "Step 5: Substitute back: $-2\\cos(\\sqrt{x})$."]', '\int f(g(x))g''(x)dx = \int f(u)du', 'math.calculus.substitution.differential_missing_factor', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:56.304Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a10f631289fbf369d1c75a6027e8c5bb', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vectors', 'Vectors', 'Section formula (internal division)', '[]', '["position vector","section formula","ratio division","3‑D coordinate geometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Find the coordinates of the point that divides the line segment joining \(A(2,-1,3)\) and \(B(8,5,-1)\) internally in the ratio \(2:3\) (AP:PB = 2:3).', '["(4.4, 1.4, 1.4)", "(5.0, 2.0, 0.0)", "(3.2, 0.8, 2.8)", "(6.0, 3.0, -2.0)"]', '(4.4, 1.4, 1.4)', 'Using the internal section formula \(\displaystyle \left(\frac{n x_1 + m x_2}{m+n},\frac{n y_1 + m y_2}{m+n},\frac{n z_1 + m z_2}{m+n}\right)\) with \(m=2, n=3\) gives \((4.4,1.4,1.4)\).', '["Step 1: Identify the ratio m:n = 2:3 (AP:PB).", "Step 2: Apply the section formula for each coordinate.", "Step 3: Compute x = (3·2 + 2·8)/5 = 22/5 = 4.4.", "Step 4: Compute y = (3·(-1) + 2·5)/5 = 7/5 = 1.4.", "Step 5: Compute z = (3·3 + 2·(-1))/5 = 7/5 = 1.4."]', 'P = ( (n x_1 + m x_2)/(m+n), ... )', 'math.geometry.vector.section_formula_ratio', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:56.380Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a1167595d0b1ae55c8adb99afcc2c60f', 'JEEMains', '12', 'Mathematics', 'math_12_jm_continuity_differentiability', 'Continuity and Differentiability', 'Parametric differentiation d²y/dx²', '[]', '["parametric differentiation","chain rule","product rule"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 25, 0.0, 'If $y = \frac{dx}{dt}$, find $\frac{d^2y}{dx^2}$.', '[]', '0', 'Step 1: We know that $y = \frac{dx}{dt}$.,Step 2: We can find $\frac{d^2y}{dx^2}$ by differentiating $y$ with respect to $x$. ,Step 3: Since $y = \frac{dx}{dt}$, we can use the chain rule to find $\frac{dy}{dx}$. ,Step 4: The chain rule states that $\frac{dy}{dx} = \frac{dy}{dt} \cdot \frac{dt}{dx}$.,Step 5: Since $\frac{dy}{dt} = \frac{d^2x}{dt^2}$ and $\frac{dt}{dx} = \frac{1}{\frac{dx}{dt}}$, we can substitute these values into the chain rule. ,Step 6: Therefore, $\frac{dy}{dx} = \frac{d^2x}{dt^2} \cdot \frac{1}{\frac{dx}{dt}}$.,Step 7: Since $y = \frac{dx}{dt}$, we can substitute this value into the expression for $\frac{dy}{dx}$. ,Step 8: Therefore, $\frac{dy}{dx} = \frac{d^2x}{dt^2} \cdot \frac{1}{y}$.,Step 9: Now, we can find $\frac{d^2y}{dx^2}$ by differentiating $\frac{dy}{dx}$ with respect to $x$. ,Step 10: Since $\frac{dy}{dx} = \frac{d^2x}{dt^2} \cdot \frac{1}{y}$, we can use the product rule to find $\frac{d^2y}{dx^2}$. ,Step 11: The product rule states that $\frac{d}{dx}(uv) = u\frac{dv}{dx} + v\frac{du}{dx}$.,Step 12: Therefore, $\frac{d^2y}{dx^2} = \frac{d}{dx}\left(\frac{d^2x}{dt^2} \cdot \frac{1}{y}\right)$.,Step 13: Using the product rule, we get $\frac{d^2y}{dx^2} = \frac{d^2x}{dt^2} \cdot \frac{d}{dx}\left(\frac{1}{y}\right) + \frac{1}{y} \cdot \frac{d}{dx}\left(\frac{d^2x}{dt^2}\right)$.,Step 14: Since $\frac{d}{dx}\left(\frac{1}{y}\right) = -\frac{1}{y^2} \cdot \frac{dy}{dx}$ and $\frac{d}{dx}\left(\frac{d^2x}{dt^2}\right) = 0$, we can substitute these values into the expression for $\frac{d^2y}{dx^2}$. ,Step 15: Therefore, $\frac{d^2y}{dx^2} = \frac{d^2x}{dt^2} \cdot \left(-\frac{1}{y^2} \cdot \frac{dy}{dx}\right) + \frac{1}{y} \cdot 0$.,Step 16: Simplifying the expression, we get $\frac{d^2y}{dx^2} = -\frac{d^2x}{dt^2} \cdot \frac{1}{y^2} \cdot \frac{dy}{dx}$.,Step 17: Since $y = \frac{dx}{dt}$, we can substitute this value into the expression for $\frac{d^2y}{dx^2}$. ,Step 18: Therefore, $\frac{d^2y}{dx^2} = -\frac{d^2x}{dt^2} \cdot \frac{1}{\left(\frac{dx}{dt}\right)^2} \cdot \frac{dx}{dt}$.,Step 19: Simplifying the expression, we get $\frac{d^2y}{dx^2} = -\frac{d^2x}{dt^2} \cdot \frac{1}{\frac{dx}{dt}}$.,Step 20: Since $\frac{d^2x}{dt^2} = \frac{d^2y}{dt^2}$ and $\frac{dx}{dt} = y$, we can substitute these values into the expression for $\frac{d^2y}{dx^2}$. ,Step 21: Therefore, $\frac{d^2y}{dx^2} = -\frac{d^2y}{dt^2} \cdot \frac{1}{y}$.,Step 22: Since $y = \frac{dx}{dt}$, we can substitute this value into the expression for $\frac{d^2y}{dx^2}$. ,Step 23: Therefore, $\frac{d^2y}{dx^2} = -\frac{d^2y}{dt^2} \cdot \frac{1}{\frac{dx}{dt}}$.,Step 24: Simplifying the expression, we get $\frac{d^2y}{dx^2} = -\frac{d^2y}{dt^2} \cdot \frac{1}{y}$.,Step 25: Therefore, $\frac{d^2y}{dx^2} = 0$.', '["Step 1: Differentiate $y = \\frac{dx}{dt}$ with respect to $x$.", "Step 2: Use the chain rule to find $\\frac{dy}{dx}$.", "Step 3: Differentiate $\\frac{dy}{dx}$ with respect to $x$ to find $\\frac{d^2y}{dx^2}$.", "Step 4: Simplify the expression for $\\frac{d^2y}{dx^2}$.", "Step 5: Substitute the values of $y$ and $\\frac{dy}{dx}$ into the expression for $\\frac{d^2y}{dx^2}$.", "Step 6: Simplify the expression for $\\frac{d^2y}{dx^2}$.", "Step 7: Therefore, $\\frac{d^2y}{dx^2} = 0$."]', 'parametric differentiation', 'math.cd.parametric_differentiation.chain_rule', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:59:40.057Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a11693cfd0f29f92ed929dff00b07ecb', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Equation of SHM x=A sin(ωt+φ)', '[]', '["SHM","amplitude","displacement","equation"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, 0.0, 'A particle executes SHM with displacement $x = 5\sin(3t + \pi/4)$. What is its amplitude?', '[]', '5', 'Amplitude is the coefficient of sine in SHM equation $x = A\sin(\omega t + \phi)$.', '["Step 1: Compare with $x=A\\sin(\\omega t+\\phi)$", "Step 2: Identify $A=5$"]', 'x = A \sin(\omega t + \phi)', 'physics.shm.amplitude_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:22.644Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a11b472c769df39d5ade86aecf09b487', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_continuity', 'Calculus', 'Continuity and Differentiability', '["math_12_ja_piecewise"]', '["continuity","differentiability","corner point","piecewise function","limit"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 5, -2.0, 'Consider the piecewise function
$$
 f(x)=\begin{cases}
 x^{2} & \text{if } x\le 0,\\
 x & \text{if } x>0.
 \end{cases}
$$
Which of the following statements are correct? (Select all that apply)', '["$f(x)$ is continuous at $x = 0$.", "$f(x)$ is differentiable at $x = 0$.", "$f(x)$ has a corner point at $x = 0$.", "$f(x)$ has a cusp at $x = 0$."]', '["$F(X)$ IS CONTINUOUS AT $X = 0$.", "$F(X)$ HAS A CORNER POINT AT $X = 0$."]', 'At $x=0$, the left‑hand limit $\lim_{x\to0^-}x^2=0$ and the right‑hand limit $\lim_{x\to0^+}x=0$, so $f$ is continuous. The left derivative $\left.\frac{d}{dx}x^2\right|_{0}=0$ while the right derivative $\left.\frac{d}{dx}x\right|_{0}=1$, hence the derivatives are unequal – the function is not differentiable and a corner occurs.', '["Step 1: Evaluate the limits from the left and right at $x=0$.", "Step 2: Compare the limits to $f(0)$ to test continuity.", "Step 3: Compute the left‑hand derivative $2x$ at $x=0$.", "Step 4: Compute the right‑hand derivative $1$ at $x=0$.", "Step 5: Since the derivatives differ, conclude non‑differentiability and identify a corner."]', 'Continuity: $\lim_{x\to c}f(x)=f(c)$; Differentiability: left and right derivatives must be equal', 'math.calculus.continuity_differentiability_corner', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:24.040Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a11c8d5012bd5eb101679c78b1639065', 'NEET', '12', 'Biology', 'bio_12_neet_biotech_ethics', 'Biotechnology', 'Ethical Issues in GM Crops', '[]', '["genetically modified crops","biodiversity","patent","seed saving","ethical concerns"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which of the following statements correctly reflects an ethical concern associated with the commercial cultivation of genetically modified (GM) crops?', '["GM crops may lead to reduced biodiversity by outcompeting native plant species.", "GM crops guarantee higher nutritional value for all consumers regardless of local dietary needs.", "Patenting of GM seeds can restrict farmers'' traditional practice of seed saving and exchange.", "GM crops eliminate the need for any pesticide applications."]', 'GM crops may lead to reduced biodiversity by outcompeting native plant species.', 'The main ethical worries are loss of biodiversity and the restriction of farmers'' rights due to patents. Options B and D are overly optimistic, while C is also an ethical issue but the question asks for a single correct statement; A directly addresses biodiversity loss.', '["Step 1: Identify the two major ethical themes – environmental impact and farmers'' rights.", "Step 2: Evaluate each option against these themes; option A mentions biodiversity loss, which is a recognized concern.", "Step 3: Confirm that the other options contain inaccurate absolutes or misrepresent the technology."]', '', 'biology.ethics.gm_crop_patent', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:44:28.618Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a11d04c5f7a203f24dd6a00905006528', 'NEET', '12', 'Biology', 'bio_12_neet_genetics_epistasis', 'Advanced Genetics for NEET', 'Epistasis types — dominant recessive hypostatic hypostasis', '[]', '["epistasis","gene interaction","dominant epistasis","phenotypic ratio","dihybrid cross","genetic masking"]', 0, 0, '["NEET","Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'In a dihybrid cross, gene $A$ masks expression of gene $B$. If $A$ is dominant, what is this interaction called?', '["Dominant epistasis", "Recessive epistasis", "Complementary gene action", "Codominance"]', 'Dominant epistasis', 'When a dominant allele at one gene masks another gene, it''s dominant epistasis (e.g., squash color).', '["Step 1: Identify masking by dominant allele", "Step 2: Match to epistasis type"]', '', 'biology.genetics.epistasis_type_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:03:38.503Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a121cd99291cae41e3e92188128fe9fc', 'Board', '10', 'Science', 'sci_10_board_mendelian_monohybrid', 'Heredity and Evolution', 'Mendelian Genetics', '[]', '["Mendel","monohybrid cross","dominant","recessive","phenotypic ratio"]', 0, 0, '[]', 'MCQ', NULL, 0, 1350, 'BOARD_EASY', 4, 0.0, 'In Mendel''s monohybrid cross of pea plants (heterozygous tall × heterozygous tall), what is the expected phenotypic ratio in the F₂ generation?', '["3 tall : 1 dwarf", "1 tall : 1 dwarf", "9 tall : 3 dwarf : 4 intermediate", "2 tall : 2 dwarf"]', '3 tall : 1 dwarf', 'A heterozygous tall (Tt) × Tt cross yields genotypes TT, Tt, Tt, tt. The dominant phenotype (tall) appears in 3 out of 4 offspring, giving a 3:1 ratio.', '["Step 1: Write the genotypes of the parents (Tt × Tt).", "Step 2: Construct a Punnett square to obtain TT, Tt, Tt, tt.", "Step 3: Identify phenotypes: TT and Tt are tall, tt is dwarf.", "Step 4: Count tall : dwarf = 3 : 1."]', '', 'biology.genetics.mendelian_ratio', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:31:58.290Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a136a1a420d9f1bf3d51da754f5db8a1', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jadv_partial_fractions', 'Mathematics', 'Integration by partial fractions', '["math_12_jadv_algebra"]', '["partial fractions","irreducible quadratic","rational integration","decomposition","algebraic factorization"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Evaluate the integral $$\int \frac{2x+3}{x^3+3x^2+4x+12}\,dx$$. The denominator can be factored as a product of a linear factor and an irreducible quadratic. Choose the correct statements about its partial‑fraction decomposition.', '["The decomposition is $\\frac{A}{x+2} + \\frac{Bx+C}{x^2+2x+6}$", "The constants satisfy $A=1$, $B=2$, $C=-1$", "The integral can be written as $\\int \\frac{A}{x+2}\\,dx + \\int \\frac{Bx+C}{x^2+2x+6}\\,dx$", "The quadratic factor $x^2+2x+6$ can be further factored over real numbers"]', '["THE DECOMPOSITION IS $\\FRAC{A}{X+2} + \\FRAC{BX+C}{X^2+2X+6}$", "THE INTEGRAL CAN BE WRITTEN AS $\\INT \\FRAC{A}{X+2}\\,DX + \\INT \\FRAC{BX+C}{X^2+2X+6}\\,DX$"]', 'Factor the cubic as $(x+2)(x^2+2x+6)$. Set $\frac{2x+3}{(x+2)(x^2+2x+6)} = \frac{A}{x+2}+\frac{Bx+C}{x^2+2x+6}$, clear denominators and equate coefficients to find $A$, $B$, $C$. The quadratic $x^2+2x+6$ has discriminant $4-24<0$, so it is irreducible over the reals. Hence the decomposition and the split of the integral are valid, while the constants in option B are incorrect and the quadratic cannot be factored further.', '["Step 1: Factor the denominator: $x^3+3x^2+4x+12 = (x+2)(x^2+2x+6)$.", "Step 2: Assume $\\frac{2x+3}{(x+2)(x^2+2x+6)} = \\frac{A}{x+2}+\\frac{Bx+C}{x^2+2x+6}$ and multiply through by the denominator.", "Step 3: Expand and equate coefficients of like powers of $x$ to solve for $A$, $B$, $C$.", "Step 4: Recognize that $x^2+2x+6$ has negative discriminant, so it remains irreducible; write the integral as the sum of two simpler integrals."]', '∫dx/(x^2+bx+c) = \frac{2}{\sqrt{4c-b^2}}\tan^{-1}\left(\frac{2x+b}{\sqrt{4c-b^2}}\right)', 'math.calculus.partial_fractions.irreducible_quadratic', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:26:50.834Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a138d75bcfc12e0dc6df914ab5812b17', 'Board', '9', 'Mathematics', 'math_09_algebraic_expressions', 'Algebraic Expressions', 'Degree of a term', '[]', '["degree","exponent","polynomial term","algebra"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'CLASS_9_BASIC', 3, 0.0, 'In the algebraic expression $3x^{2}y - 5xy^{3} + 7$, what is the degree of the term $-5xy^{3}$?', '["3", "4", "5", "6"]', '4', 'The degree of a term is the sum of the exponents of all variables in that term. For $-5xy^{3}$, the exponent of $x$ is 1 and that of $y$ is 3, giving a total degree of $1+3=4$. Hence the correct answer is 4.', '["Step 1: Identify the variables and their exponents in the term $-5xy^{3}$.", "Step 2: Add the exponents: $1$ (for $x$) + $3$ (for $y$) = $4$.", "Step 3: State that the degree of the term is $4$."]', 'Degree = sum of exponents of variables in a term', 'math.algebra.degree_misinterpretation', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1250 and target exam Board', '2026-05-20T12:39:52.749Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a13b0b67bd442d7054e318ee74fedea9', 'Board', '9', 'Mathematics', 'math_9_probability_classical', 'Probability', 'Classical probability introduction', '[]', '["classical probability","sample space","even numbers","fair die"]', 0, 0, '[]', 'MCQ', NULL, 0, 1195, 'CLASS_9_BASIC', 3, 0.0, 'A fair six‑sided die is rolled once. What is the probability of obtaining an even number?', '["1/2", "1/3", "2/3", "1/6"]', '1/2', 'Even numbers on a die are 2, 4, 6 → 3 favorable outcomes. Total outcomes = 6. Probability = 3/6 = 1/2.', '["Step 1: List the even numbers on a die.", "Step 2: Count favorable outcomes (3).", "Step 3: Divide by total outcomes (6) to get probability."]', 'Probability = favorable outcomes / total outcomes', 'math.probability.classical', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1195 and target exam Board', '2026-05-22T14:09:08.502Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a13d3f9daf897b1cefa71adaf8b2446e', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_group15', 'p-Block Elements', 'Group 15 Properties', '[]', '["antimony","metalloid","oxidation state","allotropy"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements about antimony (Sb) is correct?
A. It exists in only one allotropic form.
B. Its most stable oxidation state is +5.
C. It is a metalloid with a metallic luster.
D. It is a gas at room temperature.', '["It exists in only one allotropic form.", "Its most stable oxidation state is +5.", "It is a metalloid with a metallic luster.", "It is a gas at room temperature."]', 'It is a metalloid with a metallic luster.', 'Antimony is a typical metalloid; it shows a metallic sheen and has several allotropes. Its most common oxidation state is +3, not +5, and it is a solid at ambient conditions.', '["Step 1: Recall the classification of antimony as a metalloid.", "Step 2: Review its common oxidation states (mainly +3).", "Step 3: Eliminate options that contradict known physical state and allotropy."]', '', 'chemistry.pblock.group15.antimony', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:40.818Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a13e6f918b1d0df202d08e4d9e32012c', 'Board', '8', 'Science', 'sci_8_pressure_pascal', 'Force and Pressure', 'Pressure calculation using Pascal''s law', '[]', '["pressure","Pascal''s law","force","area","unit conversion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'CLASS_8_RECALL', 4, 0.0, 'A force of $200\,\text{N}$ is applied uniformly on a rectangular plate of area $0.04\,\text{m}^{2}$. What is the pressure exerted on the plate?', '["$5\\,\\text{kPa}$", "$8\\,\\text{kPa}$", "$10\\,\\text{kPa}$", "$12.5\\,\\text{kPa}$"]', '$5\,\text{kPa}$', 'Pressure $P = \frac{F}{A} = \frac{200\,\text{N}}{0.04\,\text{m}^{2}} = 5000\,\text{N m}^{-2} = 5\,\text{kPa}$.', '["Step 1: Write the pressure formula $P = F/A$.", "Step 2: Substitute $F = 200\\,\\text{N}$ and $A = 0.04\\,\\text{m}^{2}$.", "Step 3: Compute $200/0.04 = 5000\\,\\text{Pa}$.", "Step 4: Convert Pa to kPa (1 kPa = 1000 Pa) → $5\\,\\text{kPa}$."]', 'P = \frac{F}{A}', 'physics.pressure.unit_mismatch', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_8_RECALL) based on ELO score 1250 and target exam Board', '2026-05-22T13:45:32.116Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a13f0e2ecc084d18f36bb7daf8e36390', 'JEEMains', '12', 'Physics', 'phy_12_jm_modern_physics', 'Dual Nature of Radiation and Matter', 'Bohr model energy levels of hydrogen', '[]', '["Bohr model","Rydberg constant","spectral lines","hydrogen atom"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'What is the wavelength (in nm) of the photon emitted when a hydrogen atom makes a transition from the $n=3$ level to the $n=2$ level? (Use $R = 1.097\times10^{7}\,\text{m}^{-1}$)', '["656 nm", "486 nm", "410 nm", "121.6 nm"]', '656 nm', 'Using the Rydberg formula $1/\lambda = R(1/2^2 - 1/3^2) = R(5/36)$, we get $\lambda = 36/(5R) \approx 6.56\times10^{-7}\,\text{m} = 656\,\text{nm}$.', '["Step 1: Write the Rydberg formula for the transition.", "Step 2: Substitute $n_1=2$, $n_2=3$ and evaluate $1/\\lambda = R(1/4 - 1/9) = 5R/36$.", "Step 3: Solve for $\\lambda = 36/(5R)$ and compute the numerical value."]', '\frac{1}{\lambda}=R\left(\frac{1}{n_1^2}-\frac{1}{n_2^2}\right)', 'physics.modern_physics.bohr_wavelength_sign', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:26.126Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a1497bff23c1e91b15ee66f8e2c2c573', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Newton''s Law of Gravitation', '[]', '["gravitational force","Newton''s law","point masses","inverse square law","G constant"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Two point masses m₁ = 5 kg and m₂ = 10 kg are separated by a distance of 0.2 m. What is the magnitude of the gravitational force between them? (Use G = 6.67×10⁻¹¹ N·m²/kg²)', '["8.34×10⁻⁸ N", "1.67×10⁻⁸ N", "3.34×10⁻⁹ N", "6.67×10⁻⁹ N"]', '8.34×10⁻⁸ N', 'Applying Newton''s law of gravitation, F = G m₁ m₂ / r² = 6.67×10⁻¹¹ × (5×10) / (0.2)² = 8.34×10⁻⁸ N.', '["Step 1: Write Newton''s law: F = G m₁ m₂ / r².", "Step 2: Substitute G = 6.67×10⁻¹¹, m₁ = 5 kg, m₂ = 10 kg, r = 0.2 m.", "Step 3: Compute r² = 0.04 m²; then F = 6.67×10⁻¹¹ × 50 / 0.04 = 8.34×10⁻⁸ N."]', 'F = \frac{G m_1 m_2}{r^2}', 'physics.gravitation.newton_law', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:57:07.635Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a14ad0c261e3de97ab8b25aa48010793', 'JEEMains', '12', 'Physics', 'phy_12_jm_wave_optics', 'Wave Optics', 'Huygens principle wavefront', '[]', '["Huygens principle","wavefront","secondary wavelets","wave propagation","optics","coherent source","wave theory"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 1, -1.0, 'According to Huygens'' principle, each point on a wavefront acts as', '["A source of secondary waves", "A reflector of energy", "A particle of light", "A node of vibration"]', 'A source of secondary waves', 'Huygens'' principle states every point on wavefront emits secondary wavelets.', '["Step 1: Recall Huygens'' principle", "Step 2: Identify role of wavefront points", "Step 3: Correct: secondary wave sources"]', '', 'physics.waveoptics.huygens_misinterpretation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:32:20.895Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a14bc973957772c13f98f930d00466f5', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_optics_thin_film', 'Optics', 'Thin film interference', '["phy_12_ja_wave_optics"]', '["thin film interference","air wedge","fringe spacing","phase shift"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'An air wedge is formed by two glass plates inclined at a small angle \(\theta\). The wedge is illuminated by monochromatic light of wavelength \(\lambda\) in air. Which of the following statements are correct for the interference pattern observed?', '["The fringe spacing is given by \\(\\beta = \\frac{\\lambda}{2\\theta}\\).", "Bright fringes occur at points where the film thickness \\(t = \\frac{m\\lambda}{2}\\).", "A phase change of \\(\\pi\\) occurs upon reflection from the top surface of the wedge.", "The central fringe is bright."]', '["[\"THE FRINGE SPACING IS GIVEN BY \\(\\BETA = \\FRAC{\\LAMBDA}{2\\THETA}\\).\",\"A PHASE CHANGE OF \\(\\PI\\) OCCURS UPON REFLECTION FROM THE TOP SURFACE OF THE WEDGE.\",\"THE CENTRAL FRINGE IS BRIGHT.\"]"]', 'For an air wedge, the path difference is \(2t\). One of the reflections (air‑glass) introduces a \(\pi\) phase shift, so constructive interference occurs when \(2t = (m+\tfrac{1}{2})\lambda\). The fringe spacing is derived from geometry as \(\beta = \lambda/(2\theta)\). The wedge starts with zero thickness, giving a bright central fringe.', '["Step 1: Determine the phase change on reflection – only the top surface (air‑glass) gives a \\(\\pi\\) shift.", "Step 2: Write the condition for constructive interference: \\(2t = (m+\\tfrac{1}{2})\\lambda\\).", "Step 3: Relate the thickness \\(t\\) to the distance from the edge using \\(t = x\\theta\\) (small‑angle approximation).", "Step 4: Derive fringe spacing \\(\\beta = \\lambda/(2\\theta)\\) and note the bright central fringe."]', 'β = \frac{\lambda}{2\theta}', 'physics.optics.thin_film_phase_shift', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:31.476Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a14ce4a3b67d6ed093d48e1de23a37a8', 'JEEMains', '11', 'Physics', 'phy_11_jm_laws_of_motion', 'Laws of Motion', 'Constraint motion with inextensible string', '[]', '["Newton''s laws","inextensible string","system of masses","acceleration","free-body diagram"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, -1.0, 'A smooth horizontal table supports a block of mass $8\,\text{kg}$ attached to a hanging block of mass $2\,\text{kg}$ via a light inextensible string over a frictionless pulley. What is the acceleration of the system (take $g=10\,\text{m s}^{-2}$)?', '["1.0 m s^{-2}", "1.5 m s^{-2}", "2.0 m s^{-2}", "2.5 m s^{-2}"]', '2.0 m s^{-2}', 'Applying Newton''s second law to the hanging mass gives $m_2 g - T = m_2 a$. For the block on the table, $T = m_1 a$. Eliminating $T$ yields $a = \frac{m_2 g}{m_1+m_2}=\frac{2\times10}{8+2}=2\,\text{m s}^{-2}$.', '["Step 1: Write $T = m_1 a$ for the block on the table.", "Step 2: Write $m_2 g - T = m_2 a$ for the hanging block.", "Step 3: Substitute $T$ from Step 1 into Step 2 and solve for $a$."]', 'a = \frac{m_2 g}{m_1+m_2}', 'physics.mechanics.inextensible_string_sign', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:22.120Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a14d8e824ad044cd018ae4342e4ae4fc', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vector_algebra', 'Vector Algebra', 'Section formula in vectors', '[]', '["position vector","midpoint","section formula","vector addition","vector division"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'If $\vec{A} = 2\hat{i} + 3\hat{j}$, $\vec{B} = 4\hat{i} - \hat{j}$, position vector of midpoint is:', '["$3\\hat{i} + \\hat{j}$", "$6\\hat{i} + 2\\hat{j}$", "$\\hat{i} + 2\\hat{j}$", "$5\\hat{i} - \\hat{j}$"]', '$3\hat{i} + \hat{j}$', 'Midpoint = $\frac{\vec{A} + \vec{B}}{2} = \frac{(6\hat{i} + 2\hat{j})}{2} = 3\hat{i} + \hat{j}$', '["Step 1: Add vectors", "Step 2: Divide by 2", "Step 3: Get $3\\hat{i} + \\hat{j}$"]', '\vec{M} = \frac{\vec{A} + \vec{B}}{2}', 'math.vectors.midpoint_formula', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:07:33.260Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('a150948d57a7f6adffe5db4b73578dd4', 'Board', '9', 'Mathematics', 'math_9_board_factorisation', 'Algebraic Expressions', 'Factorisation identities', '[]', '["square of binomial","expansion","identity"]', 0, 0, '[]', 'MCQ', NULL, 0, 940, 'CLASS_9_BASIC', 2, 0.0, 'What is the expanded form of $(x+3)^2$?', '["x^2+6x+9", "x^2+9", "x^2+3x+9", "x^2+6"]', 'x^2+6x+9', 'Apply $(a+b)^2 = a^2+2ab+b^2$.', '["Step 1: $x^2 + 2\\times x\\times3 + 3^2$", "Step 2: Simplify to $x^2+6x+9$"]', '$(a+b)^2 = a^2+2ab+b^2$', 'mathematics.algebra.factorisation', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:53:33.895Z', -1);
